                    [0x44cc3f3f7d3fe1e0UL] = "Al menos la electricidad ha vuelto... pero ¿qué demonios pasa con las cámaras de seguridad?",
                    [0x45112e69a0ede541UL] = "Hay un piloto, prisionero como vosotros, en el Bloque D. Si alguien puede sacaros de aquí, es él. Yo os llevo hasta él, pero primero ayudadme a matar a Balista.",
