                    [0x21ca3b0f1921b2f0UL] = "¡No podéis tratarnos así!",
                    [0x23f457d3dc9522ebUL] = "¡Dos!",
                    [0x2548fccef3d6e3f0UL] = "¡Buen trabajo ahí fuera! ¡Vaya forma de encargarte de esos macarras!",
                    [0x2a75dd56ca6fef83UL] = "Je je je...",
                    [0x2b030ca41081902aUL] = "Bromista",
                    [0x305903dfa72e5681UL] = "Amén a eso.",
                    [0x3228cdb77e06939eUL] = "¡Buen trabajo! ¡Pero ahora empieza la verdadera pelea!",
                    [0x403edcea71ed28f2UL] = "¡Que comience la pelea!",
                    [0x40520bc2d689e8bfUL] = "¡Yo no me alisté para esto!",
                    [0x40bacd1373b04133UL] = "Figura Sombría",
                    [0x421cdc4d883c8583UL] = "¡Nos están dando!",
                    [0x4246cde8955c0d0aUL] = "¿Qué intentáis hacer, eh? ¡Aunque destruyáis el espectáculo, no podéis volar todo el estudio!",
                    [0x466826e5b94c6438UL] = "¡Qué demonios! ¡¡¡QUÉ DEMONIOS!!!",
                    [0x4833e9b1cf715897UL] = "¿Ah, sí, saco de carne?",
                    [0x49c11f74d2d221b6UL] = "¡El helicóptero debe ser destruido!",
                    [0x548033483ff07773UL] = "¡Arriba, superluchadores! ¡Hay trabajo que hacer!",
                    [0x55149a4460de4b70UL] = "...¡y recordad: DIVERTÍOS!",
                    [0x558b436a14b705f3UL] = "¡Vamos! El espectáculo empieza y tú eres la gran estrella.",
                    [0x57baa73f374e4b28UL] = "¡Gran estrella!\n¡Je je!",
                    [0x585ea9637c40eb85UL] = "Ugh, todo el mundo es crítico...",
                    [0x590434a5c8266949UL] = "Pero supón que alguien derribara la torre de transmisión. Supón que alguien detuviera la señal...",
                    [0x593733f7399f7e59UL] = "Se hace tarde.",
                    [0x5e527bdbd65a1c2aUL] = "¡Tengo una buena carrera y no voy a dejar que un par de morones de bioingeniería la arruinen!",
                    [0x5e5bdfb945b89585UL] = "Estoy seguro de que te das cuenta de que no vas a salir de este edificio. Todas las salidas están cortadas y vienen más soldados.",
                    [0x6912caa2276adbb7UL] = "¡¿Qué demonios fue eso?!",
                    [0x6aae9fd4dc8010c2UL] = "¡Vamos! ¡El público no muerde! ¡Je je!",
                    [0x6ea9fdd66ed01b03UL] = "¡Largo, chaval!",
                    [0x6f6f696a6fd2bd8eUL] = "¿Qué equipo vencerá en el Pozo? ¡Hora de averiguarlo!",
                    [0x70a710fe93868301UL] = "Solo relájate y haz lo que te salga natural.",
                    [0x716d631bdc4e252fUL] = "¡Vaya pelea! ¡Damas y caballeros...",
                    [0x726248305e62397dUL] = "¡Siete, ocho!",
                    [0x737ebf3c0d67cbd4UL] = "Por tu bien espero que... ASEGURES los cuerpos. Hay muchos que querrían poner sus manos sobre esos especímenes.",
                    [0x745524d8e00450beUL] = "¡Vamos, sacos de carne! ¡Empieza el show!",
                    [0x759cb1960641dd4bUL] = "¿Cuerpos?",
                    [0x76590b86f59c73cbUL] = "¡Muy bien, listillo, es tu último aviso! ¡Voy a contar hasta diez y será mejor que te largues antes de que acabe!",
                    [0x7cb05c036d2c4aa9UL] = "¡Uno!",
                    [0x82201369d24c01faUL] = "¡Hecho!\n¡Je je!",
                    [0x847673fe434aab35UL] = "¡Matadlos a todos!",
                    [0x857671edfdba06d4UL] = "¡Eras una ESTRELLA! ¡Le dabas al pueblo lo que quería! ¡Sin eso, qué eres? ¡Solo soldaditos de juguete inútiles y rotos!",
                    [0x8593736b30e839c0UL] = "...¡LA ÚLTIMA BATALLA!",
                    [0x8d30cbd182017c10UL] = "¡23 muertes más y me dan mi propio programa de cocina!",
                    [0x8df489f87cc6a52cUL] = "¡Esto lo arreglará!",
                    [0x8e5f0f7f5c0cbb8aUL] = "¡Estáis acabados, superluchadores! ¡No volveréis a trabajar en esta ciudad!",
                    [0x8f1e57d77f5fb234UL] = "¡Extra, extra! ¡Estudio de TV en ruinas! ¡Querido rostro mediático presuntamente muerto! ¡Programa número 1 cancelado indefinidamente! ¡Léanlo todo! ¡Solo en el Sunny City Times!",
                    [0x90f99afdd0b387b5UL] = "¡Argh!",
                    [0x94371d46ab899fceUL] = "¡Idiotas! Si ese cristal no fuera perfectamente indestructible...",
                    [0x96cfa4c69e8d418dUL] = "...¡LOS SUPERLUCHADORES!",
                    [0x97ba63e54f080fd7UL] = "¡¿Qué...!?",
                    [0x97c9b369d808ee00UL] = "¡Miedo escénico!\n¡Je je!",
                    [0x9d225ae156a9deb8UL] = "Piloto",
                    [0x9ed352df60c04af4UL] = "¡Tres!\n¡Je!",
                    [0xa298bb2dba5188a6UL] = "¡Oh, vaya!",
                    [0xac82644893598f19UL] = "Ninguno encontrado, señor. La torre cayó sobre tres manzanas. Las unidades están en camino. Es un maldito desastre, señor.",
                    [0xaca9b9d39992fc48UL] = "¡¡DIEZ!!",
                    [0xad1436378a5175c9UL] = "Vosotros, superluchadores, ¿por qué no podéis simplemente seguir las reglas?",
                    [0xae134444f7c26076UL] = "¡Espectáculo!\n¡Je je!",
                    [0xb483ac5f4a34476eUL] = "¡Eh, todo es parte del espectáculo, amigos! ¡Volvemos enseguida después de estos mensajes!",
                    [0xb78b4049d2165930UL] = "¿No veis que estamos prestando un servicio público? ¡Mantenemos el orden! ¡Sin Superfighters, habría CAOS!",
                    [0xb81f65f163aea663UL] = "¡Buen trabajo! Tómate un respiro antes de tu próximo desafío.",
                    [0xc15f97b9f9a0bf19UL] = "¡Cinco!",
                    [0xc1956c95db4f1635UL] = "¡No muerde!\n¡Je je!",
                    [0xc285478a7ef5c1ddUL] = "¡Extra! ¡Extra! ¡Novedades! ¡Los culpables podrían seguir sueltos! ¡Búsqueda en marcha en...",
                    [0xc4344d31c649a69aUL] = "¡Increíble! ¡El Equipo Azul sigue en pie! ¡Vamos con más!",
                    [0xc5a3ed4ef701c31bUL] = "No hay a dónde ir salvo arriba.",
                    [0xc8814e7e4c55afbdUL] = "Voz del Altavoz",
                    [0xc8b4fbbda23d60d2UL] = "Damas y caballeros, ¿podrían dar la bienvenida al escenario a...",
                    [0xc8c63ccd03e9ac5cUL] = "Toda esta ciudad se está volviendo loca. Y va a empeorar. Lo presiento.",
                    [0xcad5dabf8a1ecadcUL] = "Eh... ¿jefe?",
                    [0xcf8171b349c00823UL] = "¡JE JE JE!",
                    [0xd04ab4fb2986fad5UL] = "Ahora es hora de un merecido descanso. ¡Dulces sueños!",
                    [0xd0b4e6c8d948c128UL] = "¡Guardias! ¡¡DETENEDLOS!!",
                    [0xd107308732c7068dUL] = "¡Matarme no cambiará nada! Solo soy la fachada... el hombre del traje elegante. Puedo ser reemplazado... ¡pero no dejaré que pase!",
                    [0xd1a5c5ce237089abUL] = "Entonces, ¿quieres hacer algo luego?",
                    [0xd25289172c636d65UL] = "¡El Equipo Azul vence!",
                    [0xd4bc894a27001cf2UL] = "Oooooh.\n...Sí, supongo que sí.",
                    [0xd6e0acc5ae941713UL] = "El Bromista",
                    [0xd7ae1a2beb4b3228UL] = "¡Esta vez sin cazadores, solo la flor y nata: superluchadores vitaminados y locos por la batalla, directos de los tanques!",
                    [0xd8a2da16e9c7b997UL] = "¡Vosotros... no... habéis ganado!...",
                    [0xd9ce7ca456113fb7UL] = "¡Ahora veamos cómo se las arreglan con fuego real! ¡Es hora de...",
                    [0xda4c2730e89389e5UL] = "¡Ahí, acribilladlos!",
                    [0xe0b85b403f25d327UL] = "No de ESA manera, sargento.",
                    [0xe13045c4ba53f183UL] = "Telón... abajo...",
                    [0xe51e11442202a632UL] = "En algún lugar de Ciudad Soleada\n20XX",
                    [0xe8d08ca0c960add4UL] = "Vienen más soldados. Será mejor que sigas moviéndote.",
                    [0xea7831fb17de8c48UL] = "Se te acaba el tiempo. Vienen.",
                    [0xeee6f11d36af4eccUL] = "No querrás acabar como estos pobres desgraciados. Supongo que les dio miedo escénico, ¡je je!",
                    [0xef6bff69b221b98dUL] = "¿Qué haría la gente, me pregunto, sin su preciado entretenimiento?",
                    [0xefe036c18f965932UL] = "¡Eso es todo, amigos! PERO no olvidéis sintonizar mañana, ahí es cuando empieza la pelea DE VERDAD.",
                    [0xf231e5083f325b35UL] = "¡Cerdos desagradecidos! ¿Qué haríais sin nosotros?",
                    [0xf34bbac8ee388f22UL] = "¡Eso DOLIÓ! ¡Voy a disfrutar matándote!",
                    [0xf4f217f8d4781209UL] = "¡Nueve!",
                    [0xf838cce5cc35ccdeUL] = "Es algo en lo que pensar, supongo.",
                    [0xf84fcce272aa881dUL] = "¡Mierda!",
                    [0xfb2d0576fdf4511fUL] = "Noche dura, ¿eh?",
                    [0xfc2d3c1ce47a805eUL] = "¡Nos retiramos!",
                    [0xfdceebfbb5ed9ec2UL] = "¡Vienen más soldados! ¡Estáis atrapados aquí! ¡Más os vale rendiros!",
                    [0xfe9e91d49ea5398fUL] = "Esta es tu parada.",
                },
            },
            ["a4244c9d-2ef2-40d7-acb2-dcf1579b5056"] = new()
            {
                ["es"] = new()
                {
                    [0x355f12fe77de5784UL] = "¡Esto no ha terminado, maderos! ¡Estáis acabados! ¡MetroLaw es el futuro!",
                    [0x417cd86cc0ca6c17UL] = "De lo contrario, se les cobrará por completo cualquier daño adicional a edificios de valor cultural durante su arresto...",
                    [0x425ee91164382a0aUL] = "Sus hombres deberían aprender a no apuntar con sus armas a un compañero. Somos los detectives McBride y Santana, del SCPD. Nosotros nos encargamos.",
                    [0x466aae9dccce80d5UL] = "Ah, pero esta sigue siendo una comisaría del SCPD. Lo siento, oficial. Si quiere su premio, tendrá que seguir los canales adecuados.",
                    [0x8050359da2050ad6UL] = "Ayúdame a esposarlos, Santana. Nos vamos a la central.",
                    [0x8422c9c595e7687cUL] = "¡P-pero QUÉ!",
                    [0xa42e1ea0d7d127c8UL] = "Muy bien, chicos, esposen rápido a estos sacos de carne antes de que despierten.",
                    [0xb9158363e1220395UL] = "¡Largo, aficionados! Estos son los sacos de carne que volaron la estación de TV. Son propiedad del gobierno.",
                    [0xc1e47df7de9703a5UL] = "Al resistirse al arresto, acepta los términos y condiciones tal como se los he presentado. De acuerdo, sargento, puede proceder con el arresto.",
                    [0xc8814e7e4c55afbdUL] = "Voz del Altavoz",
                    [0xddc4eae441a43c65UL] = "Empiezo a pensar que el comisario tiene razón... ¡Eres un arma descontrolada, Johnny!",
                    [0xe14aefb8dc626bcbUL] = "¡Atención, superluchadores! ¡Estáis rodeados! ¡Ríndanse ahora y recibirán el premiado cuidado profesional de MetroLaw...",
                },
            },
            ["cb000516-a024-42fd-85e5-a041817a4723"] = new()
            {
                ["es"] = new()
                {
                    [0x07e18ce308582bf0UL] = "¿Cerebros...?",
                    [0x626cdf2178e4e3efUL] = "¡N-n-no! ¡¡¡AAAAARGH!!!",
                    [0x9068cf7da320c183UL] = "¡Socorro! ¿Hay alguien ahí dentro?!",
                    [0xa5dfdcf88e6e8a61UL] = "¡Oh, Dios, vienen!",
                    [0xfef9afddb45746d8UL] = "Zombi",
                },
            },
        };
    }
